<script setup>
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { useQuasar } from 'quasar'
import { useRoute, useRouter } from 'vue-router'
import PageHeader from '../components/PageHeader.vue'
import ContextHelp from '../components/ContextHelp.vue'
import { useAppStore } from '../stores/app.js'
import { canAction } from '../services/access.js'
import { getStoredUser } from '../services/tokens.js'
import { useWhiteLabel } from '../services/whitelabel.js'
import { http, unwrap, errorMessage } from '../services/http.js'
import { whatsappPermissionCommandFromSettings } from '../services/whatsapp.js'
import { telegramPermissionCommandFromSettings } from '../services/telegram.js'
import { createHelpGuides, filterHelpGuides, HELP_GROUPS, youtubeVideoId, youtubeWatchUrl, youtubeEmbedUrl } from '../services/help-guides.js'

const $q = useQuasar(), app = useAppStore(), route = useRoute(), router = useRouter(), { branding } = useWhiteLabel()
const mayConfigureHelp = computed(() => canAction(getStoredUser(), 'help', 'configure'))
const search = ref(''), group = ref('all'), selected = ref(String(route.query.guide || 'settings')), tab = ref('overview'), slide = ref('settings')
const guidePanel = ref(null)
const videos = ref({}), videoLoaded = ref(false), videoDialog = ref(false), videoInput = ref(''), videoError = ref(''), videoSaving = ref(false), videosLoading = ref(false), loadError = ref(''), videoTarget = ref('')
const profileImageAvailable = ref(true)
const guides = computed(() => createHelpGuides({ name:branding.appName,whatsappCommand:whatsappPermissionCommandFromSettings(app.settings),telegramCommand:telegramPermissionCommandFromSettings(app.settings),origin:window.location.origin }))
const filtered = computed(() => filterHelpGuides(guides.value,search.value,group.value))
const current = computed(() => filtered.value.find(item => item.id === selected.value) || filtered.value[0] || null)
const related = computed(() => (current.value?.related || []).map(id => guides.value.find(item=>item.id===id)).filter(Boolean))
const topicOptions = computed(() => filtered.value.map(item=>({label:item.title,value:item.id})))
const tutorialUrl = computed(() => videos.value[current.value?.id] || '')
const embedUrl = computed(() => youtubeEmbedUrl(tutorialUrl.value))
const quickGuides = computed(() => ['settings','web-connection','templates','assistant'].map(id=>guides.value.find(item=>item.id===id)))
const progressLabel = computed(() => current.value ? `${guides.value.findIndex(item=>item.id===current.value.id)+1} / ${guides.value.length} guias` : '')
function choose(id) { group.value='all';search.value='';selected.value=id;tab.value='overview';router.replace({query:{...route.query,guide:id}});nextTick(()=>guidePanel.value?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})) }
function topicChanged(id){selected.value=id;tab.value='overview';router.replace({query:{...route.query,guide:id}})}
watch(() => current.value?.id, () => {videoLoaded.value=false;tab.value='overview'})
watch(() => route.query.guide,value => {if(value && guides.value.some(item=>item.id===value)) selected.value=String(value)})
async function loadVideos(){videosLoading.value=true;loadError.value='';try{videos.value=(unwrap(await http.get('/help-guides'))||{}).videos||{}}catch(error){loadError.value=errorMessage(error,'Não foi possível carregar os vídeos. Os guias continuam disponíveis.')}finally{videosLoading.value=false}}
function editVideo(){if(!mayConfigureHelp.value)return;videoTarget.value=current.value.id;videoInput.value=tutorialUrl.value;videoError.value='';videoDialog.value=true}
async function saveVideo(){
  if(!mayConfigureHelp.value)return
  videoError.value=''
  const value=videoInput.value.trim()
  if(value&&!youtubeVideoId(value)){videoError.value='Cole um link HTTPS de vídeo do YouTube válido (watch, youtu.be ou shorts).';return}
  videoSaving.value=true
  try{
    const updated={...videos.value};if(value)updated[videoTarget.value]=youtubeWatchUrl(value);else delete updated[videoTarget.value]
    videos.value=(unwrap(await http.put('/help-guides',{videos:updated}))||{}).videos||{}
    videoLoaded.value=false;videoDialog.value=false;$q.notify({type:'positive',message:value?'Vídeo do guia salvo.':'Vídeo removido deste guia.'})
  }catch(error){videoError.value=errorMessage(error)}finally{videoSaving.value=false}
}
onMounted(()=>{if(!Object.keys(app.settings||{}).length)app.fetchSettings().catch(()=>undefined);loadVideos()})
</script>

<template>
  <q-page class="help-page">
    <PageHeader eyebrow="Aprenda no seu ritmo" title="Central de Ajuda" icon="help_center" />
    <section class="help-intro"><div><span class="help-kicker">GUIAS DO {{branding.appName}}</span><h2>Um caminho claro para<br class="desktop-break"/> cada parte do seu sistema.</h2><p>Encontre o menu, entenda cada campo e siga os passos. Do primeiro canal às automações com Aito I.A.</p></div><div class="help-intro-mark" aria-hidden="true"><q-icon name="menu_book"/><span>{{guides.length}} guias práticos</span></div></section>

    <q-carousel v-if="!search" v-model="slide" animated swipeable navigation arrows height="190px" control-color="primary" class="help-carousel" aria-label="Percursos sugeridos">
      <q-carousel-slide v-for="(item,index) in quickGuides" :key="item.id" :name="item.id" class="help-slide"><div class="help-slide-copy"><small>COMECE POR AQUI · {{String(index+1).padStart(2,'0')}}</small><h2>{{item.id==='assistant'?'Seu agente dentro do painel':item.title}}</h2><p>{{item.summary}}</p><q-btn dense flat no-caps color="primary" :label="item.id==='assistant'?'Conhecer e configurar':'Ver passo a passo'" icon-right="arrow_forward" @click="choose(item.id)"/></div><q-icon :name="item.icon" class="help-slide-icon" aria-hidden="true"/></q-carousel-slide>
    </q-carousel>

    <section class="help-browser" aria-label="Buscar um guia">
      <q-input v-model="search" outlined clearable dense placeholder="Buscar menu, configuração ou dúvida…" aria-label="Buscar na ajuda" class="help-search"><template #prepend><q-icon name="search"/></template></q-input>
      <div class="help-categories" aria-label="Categorias da ajuda"><q-chip v-for="item in HELP_GROUPS" :key="item.id" clickable :outline="group!==item.id" :class="{'help-category--selected':group===item.id}" :icon="item.icon" :aria-pressed="group===item.id" @click="group=item.id">{{item.label}}</q-chip></div>
    </section>

    <div class="help-workspace">
      <aside class="help-topic-nav" aria-label="Guias por menu"><header><strong>Explore o painel</strong><span>{{filtered.length}} tópico(s)</span></header><q-list><q-item v-for="item in filtered" :key="item.id" clickable :active="current?.id===item.id" active-class="help-topic--active" @click="topicChanged(item.id)"><q-item-section avatar><q-icon :name="item.icon"/></q-item-section><q-item-section><q-item-label>{{item.title}}</q-item-label></q-item-section><q-item-section side><q-icon name="chevron_right" size="16px"/></q-item-section></q-item><p v-if="!filtered.length" class="help-empty-nav">Nenhum guia neste filtro.</p></q-list><div class="help-topic-footer"><q-icon name="smart_toy"/><p>Precisa executar uma tarefa?<strong>Use o robô no canto do painel.</strong></p></div></aside>
      <main ref="guidePanel" class="help-main">
        <q-select v-if="filtered.length" :model-value="current?.id" :options="topicOptions" emit-value map-options outlined dense label="Escolha um guia" class="help-mobile-topics" @update:model-value="topicChanged"/>
        <section v-if="!current" class="help-no-results"><q-icon name="search_off"/><h2>Nenhum guia encontrado</h2><p>Tente outro termo ou remova o filtro de categoria.</p><q-btn flat no-caps label="Mostrar todos os guias" color="primary" @click="search='';group='all'"/></section>
        <q-card v-else flat class="help-guide-card">
          <header class="help-guide-header"><q-avatar :icon="current.icon"/><div><small>{{HELP_GROUPS.find(item=>item.id===current.group)?.label}} · {{progressLabel}}</small><h2>{{current.title}}</h2><p>{{current.summary}}</p></div><q-btn v-if="current.to&&current.id!=='help'" outline no-caps icon-right="north_east" label="Abrir no painel" color="primary" :to="current.to" class="help-open-panel"/></header>
          <q-tabs v-model="tab" align="left" dense no-caps active-color="primary" indicator-color="primary" class="help-tabs"><q-tab name="overview" icon="explore" label="Visão geral"/><q-tab name="fields" icon="tune" :label="`Configurações (${current.fields.length})`"/><q-tab name="questions" icon="help_outline" label="Dúvidas"/></q-tabs>
          <q-separator/>
          <q-tab-panels v-model="tab" animated class="help-panels">
            <q-tab-panel name="overview">
              <div class="help-overview-grid"><section class="help-step-section"><h3>Como começar</h3><ol class="help-step-list"><li v-for="(step,index) in current.steps" :key="step"><span>{{String(index+1).padStart(2,'0')}}</span><p>{{step}}</p></li></ol></section>
                <section class="help-tutorial"><header><div><q-icon name="smart_display"/><strong>Veja na prática</strong></div><q-btn v-if="mayConfigureHelp" flat round dense icon="edit" aria-label="Configurar vídeo deste guia" :disable="videosLoading||!!loadError" @click="editVideo"><q-tooltip>{{tutorialUrl?'Alterar vídeo':'Adicionar vídeo do YouTube'}}</q-tooltip></q-btn></header><q-video v-if="videoLoaded&&embedUrl" :src="embedUrl" :ratio="16/9" :title="`Tutorial de ${current.title}`" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"/><div v-else class="help-video-placeholder"><q-icon :name="tutorialUrl?'play_circle':'video_library'"/><strong>{{tutorialUrl?'Seu tutorial está pronto':'Seu vídeo pode ficar aqui'}}</strong><p>{{tutorialUrl?'Carregue o player para assistir ao conteúdo do YouTube.':'Adicione o link do treinamento da sua equipe para este tópico.'}}</p><q-btn v-if="tutorialUrl" no-caps unelevated color="primary" label="Carregar vídeo" icon="play_arrow" @click="videoLoaded=true"/><q-btn v-else-if="mayConfigureHelp" no-caps outline color="primary" label="Adicionar vídeo" :disable="videosLoading||!!loadError" @click="editVideo"/></div><a v-if="tutorialUrl" :href="tutorialUrl" target="_blank" rel="noopener noreferrer" class="help-video-link">Abrir no YouTube <q-icon name="open_in_new"/></a><small>O player externo só carrega ao clicar. O link fica salvo para os administradores desta instalação.</small></section>
              </div>
              <q-banner v-if="loadError" rounded class="help-note help-note--warning" role="alert">{{loadError}}<template #action><q-btn flat dense no-caps label="Tentar novamente" @click="loadVideos"/></template></q-banner>
              <q-banner v-for="tip in current.tips" :key="tip" rounded class="help-note"><template #avatar><q-icon name="lightbulb_outline"/></template>{{tip}}</q-banner>
              <div v-if="current.links.length" class="help-official-links"><small>NA FONTE</small><a v-for="item in current.links" :key="item.url" :href="item.url" target="_blank" rel="noopener noreferrer"><q-icon name="verified"/><span>{{item.label}}</span><q-icon name="open_in_new"/></a><p>Os nomes das telas dos provedores podem mudar; confira os passos na documentação oficial.</p></div>
              <section v-if="current.id==='logins'" class="help-profile-preview"><img v-if="profileImageAvailable" src="/comunicacao/app/meuperfil.png" alt="Exemplo da página Meu perfil do contato" loading="lazy" decoding="async" fetchpriority="low" @error="profileImageAvailable=false"/><div v-else><q-icon name="account_circle"/><span>Espaço reservado para a imagem da tela Meu perfil</span></div></section>
            </q-tab-panel>
            <q-tab-panel name="fields"><header class="help-fields-heading"><h3>O que preencher e onde encontrar</h3><ContextHelp title="Configurações e credenciais" tooltip="Como usar este guia" text="Os campos abaixo usam os nomes do painel. Quando houver uma credencial externa, a origem aparece em Como obter. Não cole tokens em campos de conteúdo público. Cadastre nos campos protegidos e salve somente após conferir a conta e o ambiente."/></header><div class="help-fields-grid"><article v-for="(item,index) in current.fields" :key="item.label" class="help-field"><span class="help-field-number">{{String(index+1).padStart(2,'0')}}</span><div><h4>{{item.label}}</h4><p>{{item.explanation}}</p><div v-if="item.where" class="help-field-source"><q-icon name="key"/><p><strong>Como obter</strong>{{item.where}}</p></div></div></article></div><div v-if="current.links.length" class="help-field-links"><q-btn v-for="item in current.links" :key="item.url" flat no-caps color="primary" icon-right="open_in_new" :label="item.label" :href="item.url" target="_blank" rel="noopener noreferrer"/></div></q-tab-panel>
            <q-tab-panel name="questions"><h3>Dúvidas que fazem diferença</h3><q-expansion-item v-for="(item,index) in current.faqs" :key="`${current.id}:${item.question}`" :default-opened="index===0" :label="item.question" icon="help_outline" class="help-faq"><p>{{item.answer}}</p></q-expansion-item></q-tab-panel>
          </q-tab-panels>
          <footer v-if="related.length" class="help-related"><small>CONTINUE EXPLORANDO</small><div><q-chip v-for="item in related" :key="item.id" clickable outline :icon="item.icon" @click="choose(item.id)">{{item.title}} <q-icon name="arrow_forward" size="14px"/></q-chip></div></footer>
        </q-card>
      </main>
    </div>

    <q-dialog v-model="videoDialog" :persistent="videoSaving"><q-card class="help-video-dialog"><header><q-avatar icon="smart_display"/><div><h2>Vídeo deste guia</h2><p>{{guides.find(item=>item.id===videoTarget)?.title}}</p></div><q-btn flat round dense icon="close" aria-label="Fechar configuração do vídeo" :disable="videoSaving" v-close-popup/></header><q-form @submit="saveVideo"><q-card-section><q-banner v-if="videoError" rounded class="bg-red-1 text-negative q-mb-md" role="alert">{{videoError}}</q-banner><q-input v-model="videoInput" outlined label="Link do YouTube" placeholder="https://www.youtube.com/watch?v=…" maxlength="2048" :disable="videoSaving" clearable/><p>Use um vídeo já publicado no YouTube. Aceita links normais, curtos e Shorts. Deixe vazio para remover o vínculo deste guia.</p><q-banner rounded class="help-note"><template #avatar><q-icon name="save"/></template>O link é salvo na instalação e permanece depois de fechar o navegador ou fazer deploy.</q-banner></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancelar" :disable="videoSaving" v-close-popup/><q-btn unelevated no-caps color="primary" type="submit" label="Salvar vídeo" :loading="videoSaving"/></q-card-actions></q-form></q-card></q-dialog>
  </q-page>
</template>

<style scoped>
.help-page{padding:clamp(16px,3vw,36px);max-width:1640px;margin:auto;color:var(--ink);min-width:0}.help-intro{display:flex;align-items:center;justify-content:space-between;gap:25px;margin:12px 0 24px;padding:8px 0}.help-kicker{font-size:10px;letter-spacing:.13em;font-weight:800;color:var(--brand-dark);text-transform:uppercase}.help-intro h2{font-size:clamp(27px,3.1vw,41px);font-weight:750;letter-spacing:-1.5px;line-height:1.2;margin:12px 0 15px}.help-intro p{font-size:14px;line-height:1.8;color:var(--muted);max-width:650px;margin:0}.help-intro-mark{display:grid;justify-items:center;gap:10px;padding:20px 35px;color:var(--brand-dark);flex:none}.help-intro-mark>.q-icon{font-size:70px}.help-intro-mark>span{font-size:11px;font-weight:700}.help-carousel{border:1px solid var(--line);border-radius:20px;background:linear-gradient(120deg,color-mix(in srgb,var(--brand) 10%,white),white);box-shadow:0 8px 30px #0a4b3c05}.help-slide{display:flex;align-items:center;justify-content:space-between;gap:25px;padding:22px 60px 35px;overflow:hidden}.help-slide-copy{max-width:690px;min-width:0}.help-slide-copy>small{font-size:9px;letter-spacing:.14em;color:var(--brand-dark);font-weight:800}.help-slide h2{font-size:23px;line-height:1.3;font-weight:750;letter-spacing:-.5px;margin:7px 0}.help-slide p{font-size:12px;line-height:1.7;margin:0 0 6px;color:var(--muted)}.help-slide .q-btn{font-size:12px;padding-left:0}.help-slide-icon{font-size:90px;color:color-mix(in srgb,var(--brand) 30%,white);margin-right:25px;transform:rotate(-8deg)}.help-carousel :deep(.q-carousel__navigation .q-btn){min-width:24px;min-height:20px;padding:3px;font-size:7px}.help-browser{display:grid;gap:12px;margin:25px 0 18px}.help-search{max-width:680px;background:white;border-radius:12px}.help-categories{display:flex;flex-wrap:wrap;gap:5px}.help-categories .q-chip{font-size:12px;margin:0;min-height:34px;border-color:var(--line);color:var(--muted)}.help-category--selected{background:var(--brand-dark);color:white!important}.help-workspace{display:grid;grid-template-columns:260px minmax(0,1fr);gap:20px;align-items:start}.help-topic-nav{position:sticky;top:85px;border:1px solid var(--line);border-radius:18px;background:white;overflow:hidden}.help-topic-nav>header{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:18px 15px;border-bottom:1px solid var(--line);font-size:12px}.help-topic-nav>header span{font-size:10px;color:var(--muted)}.help-topic-nav>.q-list{max-height:calc(100dvh - 300px);min-height:150px;overflow:auto;scrollbar-width:thin;padding:7px}.help-topic-nav .q-item{min-height:46px;border-radius:10px;padding:10px 8px;font-size:12px;line-height:1.5}.help-topic-nav :deep(.q-item__section--avatar){min-width:33px;color:var(--brand-dark)}.help-topic-nav :deep(.q-item__section--avatar .q-icon){font-size:19px}.help-topic--active{background:color-mix(in srgb,var(--brand) 12%,white);color:var(--brand-dark);font-weight:750}.help-empty-nav{padding:15px;font-size:12px;color:var(--muted)}.help-topic-footer{display:flex;gap:10px;padding:15px;background:color-mix(in srgb,var(--brand) 5%,white);border-top:1px solid var(--line)}.help-topic-footer>.q-icon{font-size:24px;color:var(--brand-dark)}.help-topic-footer p{font-size:10px;line-height:1.7;color:var(--muted);margin:0}.help-topic-footer strong{display:block;color:var(--ink);font-size:10px}.help-main{min-width:0;scroll-margin-top:88px}.help-mobile-topics{display:none}.help-guide-card{border:1px solid var(--line);border-radius:20px;background:white;overflow:hidden}.help-guide-header{display:flex;align-items:flex-start;gap:13px;padding:24px;background:linear-gradient(115deg,color-mix(in srgb,var(--brand) 5%,white),white)}.help-guide-header>.q-avatar{flex:none;background:color-mix(in srgb,var(--brand) 13%,white);color:var(--brand-dark);border-radius:13px}.help-guide-header>div{flex:1;min-width:0}.help-guide-header small{font-size:10px;color:var(--muted)}.help-guide-header h2{font-size:24px;line-height:1.3;letter-spacin